// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * Pins the normal-distribution numerics against externally computed references (libm double precision, generated
 * 2026-08-18) and against analytic identities in the extreme ranges where no double-precision reference exists.
 * Arguments named {@code a} are standardized normal deviates; erfcx references are at {@code a/sqrt(2)}.
 */
class LmdbNativeGaussianMathTest {

	private static final double SQRT2 = Math.sqrt(2.0);

	private static void assertRelative(double expected, double actual, double tolerance) {
		double scale = Math.max(Math.abs(expected), Double.MIN_NORMAL);
		assertTrue(Math.abs(actual - expected) / scale <= tolerance,
				"expected " + expected + " but was " + actual + " (rel err " + Math.abs(actual - expected) / scale
						+ ")");
	}

	@Test
	void erfcxMatchesReferenceValues() {
		assertRelative(157925920365360.2, LmdbNativeGaussianMath.erfcx(-8.0 / SQRT2), 1e-11);
		assertRelative(179.79123470433237, LmdbNativeGaussianMath.erfcx(-3.0 / SQRT2), 1e-12);
		assertRelative(2.774285957670009, LmdbNativeGaussianMath.erfcx(-1.0 / SQRT2), 1e-12);
		assertEquals(1.0, LmdbNativeGaussianMath.erfcx(0.0));
		assertRelative(0.6992376694407962, LmdbNativeGaussianMath.erfcx(0.5 / SQRT2), 1e-12);
		assertRelative(0.5231565837302466, LmdbNativeGaussianMath.erfcx(1.0 / SQRT2), 1e-12);
		assertRelative(0.24302789671112435, LmdbNativeGaussianMath.erfcx(3.0 / SQRT2), 1e-12);
		assertRelative(0.09824509242484974, LmdbNativeGaussianMath.erfcx(8.0 / SQRT2), 1e-12);
		assertRelative(0.03979523129665434, LmdbNativeGaussianMath.erfcx(20.0 / SQRT2), 1e-12);
	}

	@Test
	void erfcxIsPositiveAndDecreasingForPositiveArguments() {
		double previous = Double.POSITIVE_INFINITY;
		for (double x = 0.0; x <= 200.0; x += 0.37) {
			double value = LmdbNativeGaussianMath.erfcx(x);
			assertTrue(value > 0.0, "erfcx must stay positive at " + x);
			assertTrue(value < previous, "erfcx must decrease at " + x);
			previous = value;
		}
	}

	@Test
	void erfcxSaturatesInsteadOfOverflowingForVeryNegativeArguments() {
		assertTrue(Double.isInfinite(LmdbNativeGaussianMath.erfcx(-27.0)));
		assertTrue(Double.isFinite(LmdbNativeGaussianMath.erfcx(-26.0)));
	}

	@Test
	void logSurvivalMatchesReferenceValues() {
		assertRelative(-0.0013508099647482027, LmdbNativeGaussianMath.logSurvival(-3.0), 1e-11);
		assertRelative(-0.1727537790234499, LmdbNativeGaussianMath.logSurvival(-1.0), 1e-12);
		assertRelative(-0.6931471805599453, LmdbNativeGaussianMath.logSurvival(0.0), 1e-12);
		assertRelative(-1.1759117615936185, LmdbNativeGaussianMath.logSurvival(0.5), 1e-12);
		assertRelative(-1.8410216450092636, LmdbNativeGaussianMath.logSurvival(1.0), 1e-12);
		assertRelative(-6.607726221510348, LmdbNativeGaussianMath.logSurvival(3.0), 1e-12);
		assertRelative(-35.013437159914545, LmdbNativeGaussianMath.logSurvival(8.0), 1e-12);
		assertRelative(-203.91715537109724, LmdbNativeGaussianMath.logSurvival(20.0), 1e-12);
	}

	@Test
	void logSurvivalHandlesExtremesWithoutUnderflow() {
		// Phi(-8) = 6.22096e-16, so log survival is -6.22096e-16: the naive 1-Phi path would round it to zero
		double nearOne = LmdbNativeGaussianMath.logSurvival(-8.0);
		assertTrue(nearOne < 0.0 && nearOne > -7e-16, "logSurvival(-8) was " + nearOne);
		double veryNegative = LmdbNativeGaussianMath.logSurvival(-50.0);
		assertTrue(veryNegative <= 0.0 && veryNegative > -1e-300, "logSurvival(-50) was " + veryNegative);
		// asymptotic reference: log(1-Phi(a)) = -a^2/2 - log(a) - log(2*pi)/2 + log(1 - 1/a^2 + 3/a^4 - ...)
		double a = 100.0;
		double asymptotic = -0.5 * a * a - Math.log(a) - 0.5 * Math.log(2.0 * Math.PI)
				+ Math.log1p(-1.0 / (a * a) + 3.0 / (a * a * a * a));
		assertRelative(asymptotic, LmdbNativeGaussianMath.logSurvival(a), 1e-9);
		assertTrue(Double.isFinite(LmdbNativeGaussianMath.logSurvival(700.0)));
	}

	@Test
	void millsRatioMatchesReferenceValues() {
		assertRelative(5.052271083536931e-15, LmdbNativeGaussianMath.millsRatioUpper(-8.0), 1e-11);
		assertRelative(0.004437839042125667, LmdbNativeGaussianMath.millsRatioUpper(-3.0), 1e-12);
		assertRelative(0.7978845608028654, LmdbNativeGaussianMath.millsRatioUpper(0.0), 1e-12);
		assertRelative(1.5251352761609815, LmdbNativeGaussianMath.millsRatioUpper(1.0), 1e-12);
		assertRelative(3.2830986549304364, LmdbNativeGaussianMath.millsRatioUpper(3.0), 1e-12);
		assertRelative(8.121368112236123, LmdbNativeGaussianMath.millsRatioUpper(8.0), 1e-12);
		assertRelative(20.04975306852771, LmdbNativeGaussianMath.millsRatioUpper(20.0), 1e-12);
	}

	@Test
	void millsRatioObeysItsIdentitiesIntoTheExtremeRange() {
		double previousExcess = Double.POSITIVE_INFINITY;
		for (double a : new double[] { -8, -3, -1, 0, 0.5, 1, 3, 8, 20, 100, 700 }) {
			double lambda = LmdbNativeGaussianMath.millsRatioUpper(a);
			assertTrue(lambda > Math.max(a, 0.0), "lambda(a) > max(a,0) violated at " + a + ": " + lambda);
			double excess = lambda - a;
			assertTrue(excess < previousExcess, "lambda(a) - a must decrease, violated at " + a);
			previousExcess = excess;
		}
		// large-a expansion lambda(a) = a + 1/a - 2/a^3 + O(1/a^5)
		double a = 100.0;
		double expansion = a + 1.0 / a - 2.0 / (a * a * a);
		assertRelative(expansion, LmdbNativeGaussianMath.millsRatioUpper(a), 1e-8);
		assertEquals(0.0, LmdbNativeGaussianMath.millsRatioUpper(-40.0));
	}

	@Test
	void huberClipBoundsAndPassesThrough() {
		assertEquals(1.5, LmdbNativeGaussianMath.huberClip(1.5, 3.0));
		assertEquals(3.0, LmdbNativeGaussianMath.huberClip(17.0, 3.0));
		assertEquals(-3.0, LmdbNativeGaussianMath.huberClip(-9.0, 3.0));
		assertEquals(0.0, LmdbNativeGaussianMath.huberClip(Double.NaN, 3.0));
	}
}
